*, *::before, *::after { box-sizing: border-box; }
.card {
  width: 20rem;
  max-width: 100%;
  padding: 1rem;
  border: 2px solid #555;
}

.cards {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(16rem, 100%), 1fr));
  gap: 1rem;
}
img { max-width: 100%; height: auto; }

